import{_ as e,o as r,c as o,a2 as s}from"./chunks/framework.ChIlRNAd.js";const c=JSON.parse('{"title":"Administration","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/admin.md","filePath":"en/guide/admin.md"}'),a={name:"en/guide/admin.md"};function n(i,t,d,l,h,g){return r(),o("div",null,[...t[0]||(t[0]=[s('<h1 id="administration" tabindex="-1">Administration <a class="header-anchor" href="#administration" aria-label="Permalink to &quot;Administration&quot;">​</a></h1><p>The <strong>Admin</strong> page (<code>/admin</code>) is reserved for users with the <strong>admin</strong> role: the entry only shows for them (<strong>Administration</strong> group in the sidebar, or <strong>More › Administration</strong> on mobile), and the address sends other users back to the Overview.</p><p>Three tabs: <strong>Users</strong>, <strong>System</strong>, <strong>Audit</strong>.</p><hr><h2 id="users" tabindex="-1">Users <a class="header-anchor" href="#users" aria-label="Permalink to &quot;Users&quot;">​</a></h2><p>Search by <strong>Email or name</strong>, then the paginated list:</p><table tabindex="0"><thead><tr><th>Column</th><th>Content</th></tr></thead><tbody><tr><td><strong>User</strong></td><td>email and name</td></tr><tr><td><strong>Role</strong></td><td>Admin or User</td></tr><tr><td><strong>Status</strong></td><td>Active or Disabled</td></tr><tr><td><strong>Gmail accounts</strong></td><td>&quot;N / max accounts&quot;</td></tr><tr><td><strong>Storage</strong></td><td>archives used / quota</td></tr><tr><td><strong>Last login</strong></td><td>date, or &quot;Never logged in&quot;</td></tr></tbody></table><p><strong>Edit</strong> opens &quot;Edit user&quot;:</p><ul><li><strong>Role</strong>: User or Admin;</li><li><strong>Active account</strong>: a disabled account can no longer sign in (&quot;This account has been disabled&quot;);</li><li><strong>Maximum Gmail accounts</strong>;</li><li><strong>Storage quota (GB)</strong>.</li></ul><p>Below the form:</p><ul><li><strong>Reset password</strong>: sets a new password (at least 8 characters) to pass on to the user; their open sessions are signed out (for your own password, use Settings › Security);</li><li><strong>Delete user</strong>: after a confirmation, permanently deletes the account, its Gmail accounts and its archives. Not offered on your own account (use <a href="./settings.html#delete-my-account">Settings › Data</a>); the last active admin cannot be deleted.</li></ul><hr><h2 id="system" tabindex="-1">System <a class="header-anchor" href="#system" aria-label="Permalink to &quot;System&quot;">​</a></h2><p>&quot;Settings of this Nid instance, for every user.&quot;</p><h3 id="archive-trash" tabindex="-1">Archive trash <a class="header-anchor" href="#archive-trash" aria-label="Permalink to &quot;Archive trash&quot;">​</a></h3><ul><li><strong>Maximum time in the trash</strong>: 7, 30 or 90 days.</li><li>Current volume (&quot;N emails · size&quot;) and next purge date (or &quot;automatic purge disabled&quot;).</li><li><strong>Empty the trash now…</strong>: after confirmation (&quot;Permanently empty the trash?&quot;), deletes the trash mails from the NAS <strong>for every user</strong>. Cannot be undone.</li></ul><h3 id="archive-integrity" tabindex="-1">Archive integrity <a class="header-anchor" href="#archive-integrity" aria-label="Permalink to &quot;Archive integrity&quot;">​</a></h3><p>Checks that the NAS files match the index: &quot;Archives are intact&quot;, or the number of missing, corrupted and orphaned files. Shows the last check and the number of mails checked. &quot;Automatic check every day at 3 am.&quot;; <strong>Run a check</strong> starts one now.</p><p>When a problem is found, the <strong>Integrity alert</strong> event is notified (see <a href="./notifications.html">Notifications</a>).</p><h3 id="gmail-api-quota" tabindex="-1">Gmail API quota <a class="header-anchor" href="#gmail-api-quota" aria-label="Permalink to &quot;Gmail API quota&quot;">​</a></h3><p>Usage of the instance&#39;s Google project, all accounts: <strong>Units today</strong>, <strong>Peak per user</strong> (units per second / limit), <strong>429 responses over 24 h</strong>.</p><h3 id="jobs-of-all-users" tabindex="-1">Jobs of all users <a class="header-anchor" href="#jobs-of-all-users" aria-label="Permalink to &quot;Jobs of all users&quot;">​</a></h3><p>The 20 most recent jobs of the instance: <strong>Job</strong>, <strong>User</strong>, <strong>Status</strong>, <strong>Created</strong>.</p><hr><h2 id="audit" tabindex="-1">Audit <a class="header-anchor" href="#audit" aria-label="Permalink to &quot;Audit&quot;">​</a></h2><p>The instance log, filterable by <strong>User</strong> (email) and by <strong>Action</strong> (or <strong>All actions</strong>). Columns: <strong>Date</strong>, <strong>User</strong>, <strong>Action</strong>, <strong>Target</strong>.</p>',26)])])}const m=e(a,[["render",n]]);export{c as __pageData,m as default};
